153	// Bottom composer — the only way to type to Claude in transcript mode (the live
154	// terminal is hidden). Sends multi-line text via /api/send's paste-buffer path
155	// then Enter; the new turn shows up on the next poll. Enter submits,
156	// Shift+Enter inserts a newline (chat convention, matches Claude's own input).
157	function Composer({ target, composerRef }) {
158	  const [text, setText] = useState("");
159	  const [sending, setSending] = useState(false);
160	  const inputRef = useRef(null);
161	
162	  async function send() {
163	    const body = text;
164	    if (!body.trim() || sending) return;
165	    setSending(true);
166	    // Paste first, THEN submit as a separate Enter after a beat — a long paste
167	    // can still be rendering when a same-call Enter lands, leaving the message
168	    // staged-but-unsent in Claude's input. The delay lets the paste settle.
169	    const pasted = await apiCall("send", `/api/send?${targetQuery(target)}`, {
170	      method: "POST",
171	      headers: { "Content-Type": "application/json" },
172	      body: JSON.stringify({ paste: body }),
173	    });
174	    if (pasted) {
175	      await new Promise((r) => setTimeout(r, 250));
176	      await apiCall("send", `/api/send?${targetQuery(target)}`, {
177	        method: "POST",
178	        headers: { "Content-Type": "application/json" },
179	        body: JSON.stringify({ keys: ["Enter"] }),
180	      });
181	      setText("");
182	      if (inputRef.current) inputRef.current.style.height = "";  // back to CSS min-height
183	    }
184	    setSending(false);
185	  }
186	
187	  function onKeyDown(e) {
188	    if (e.key === "Enter" && !e.shiftKey) {
189	      e.preventDefault();
190	      send();
191	    }
192	  }
193	
194	  function onInput(e) {
195	    const el = e.currentTarget;
196	    setText(el.value);
197	    // Collapse to 0 before measuring so the box tracks content both ways
198	    // (grows and shrinks); cap matches CSS max-height.
199	    el.style.height = "0px";
200	    el.style.height = Math.min(el.scrollHeight, 140) + "px";
201	  }
202	
203	  // Paste a screenshot: upload it (deliver=false so it lands in THIS message,
204	  // not the live pane) and splice the resulting @path into the box. Claude
205	  // resolves @-paths on submit, same as the terminal's paste path.
206	  async function onPaste(e) {
207	    const items = e.clipboardData?.items || [];
208	    for (const item of items) {
209	      if (item.kind !== "file" || !item.type.startsWith("image/")) continue;
210	      const blob = item.getAsFile();
211	      if (!blob) continue;
212	      e.preventDefault();
213	      const res = await fetch(`/api/paste-image?${targetQuery(target)}&deliver=false`, {
214	        method: "POST",
215	        headers: { "Content-Type": blob.type || "image/png" },
216	        body: blob,
217	      });
218	      const d = await res.json().catch(() => ({}));
219	      if (d.ok) setText((prev) => `${prev}${prev && !prev.endsWith(" ") ? " " : ""}@${d.path} `);
220	      return;
221	    }
222	  }
223	
224	  return (
225	    <div class="transcript-composer" ref={composerRef}>
226	      <textarea
227	        ref={inputRef}
228	        class="transcript-composer-input"
229	        placeholder="Message Claude…  (Enter to send · Shift+Enter for newline · paste screenshots)"
230	        value={text}
231	        rows={1}
232	        onInput={onInput}
233	        onKeyDown={onKeyDown}
234	        onPaste={onPaste}
235	      />
236	    </div>
237	  );
238	}
239	
240	export function TranscriptView({ target, pid, selected }) {
241	  const messages = useTranscriptPoll(target, pid, selected);
242	  const scrollRef = useRef(null);
243	  const composerRef = useRef(null);
244	  // Follow the conversation: open at the bottom and stay pinned as new turns
245	  // arrive — UNLESS the user has scrolled up to read, then leave them be.
246	  const stick = useRef(true);
247	  const lastKey = useRef("");
248	
249	  const pin = () => {
250	    const el = scrollRef.current;
251	    if (el && stick.current) el.scrollTop = el.scrollHeight;
252	  };
253	
254	  // Pin ONLY when the content actually changed — not on every 2s poll (the
255	  // message list is replaced each poll even when identical). Re-pinning on an
256	  // unchanged poll is what yanked the view to the bottom while you were typing.
257	  useEffect(() => {
258	    const last = messages[messages.length - 1];
259	    const key = `${messages.length}:${last ? last.uuid : ""}:${last ? (last.tool_uses || []).length : 0}`;
260	    if (key !== lastKey.current) {
261	      lastKey.current = key;
262	      pin();
263	    }
264	  }, [messages]);
265	
266	  // The composer overlays the bottom of the (full-height) transcript. Keep the
267	  // transcript's bottom padding equal to the composer's height so the last
268	  // message always clears the box, and re-pin if we're stuck — so growing the
269	  // composer just reflows padding instead of resizing the scroll viewport (no
270	  // bounce). rAF: measure after layout settles.
271	  useEffect(() => {
272	    const box = composerRef.current;
273	    const scroll = scrollRef.current;
274	    if (!box || !scroll) return;
275	    const sync = () => {
276	      scroll.style.paddingBottom = box.offsetHeight + 14 + "px";
277	      requestAnimationFrame(pin);
278	    };
279	    sync();
280	    const ro = new ResizeObserver(sync);
281	    ro.observe(box);
282	    return () => ro.disconnect();
283	  }, []);
284	
285	  function onScroll(e) {
286	    const el = e.currentTarget;
287	    stick.current = el.scrollHeight - el.scrollTop - el.clientHeight < 80;
288	  }
289	
290	  return (
291	    <>
292	      <div class="transcript" ref={scrollRef} onScroll={onScroll}>
293	        {messages.length === 0
294	          ? <div class="transcript-empty">No transcript yet.</div>
295	          : messages.map((m) =>
296	              m.role === "system" && m.kind === "compact"
297	                ? <div key={m.uuid} class="transcript-compact"><span>context compacted</span></div>
298	                : <Turn key={m.uuid} m={m} />
299	            )}
300	      </div>
301	      <Composer target={target} composerRef={composerRef} />
302	    </>
303	  );
304	}
