file.content:
.transcript-compact {
  display: flex; align-items: center; gap: 12px;
  margin: 20px 0; color: var(--fg-4);
  font-size: 9.5px; text-transform: uppercase; letter-spacing: 0.09em;
}
.transcript-compact::before, .transcript-compact::after {
  content: ""; flex: 1; height: 1px; background: var(--line-soft);
}

/* ── turns ── */
.turn { margin: 0 0 17px; }

/* User message — understated `› text`, not a boxed callout; top-aligned. */
.turn-user {
  display: flex; gap: 9px; align-items: baseline;
  margin-bottom: 15px;
}
.turn-user-mark { color: var(--fg-3); font-weight: 600; flex: none; }
.turn-user-body { color: var(--fg-0); min-width: 0; }
.turn-user-body .md-p { font-size: 13.5px; line-height: 1.55; }

.turn-prose { color: var(--fg-1); font-family: var(--sans); font-size: 13.5px; line-height: 1.58; }
.turn-tools { margin-top: 7px; display: flex; flex-direction: column; gap: 2px; }

/* ── tool calls — Claude terminal vocabulary ── */
.tc { font-family: var(--mono); font-size: 12px; }
.tc-head {
  display: flex; align-items: baseline; gap: 7px; width: 100%;
  text-align: left; background: transparent; border: 0; color: var(--fg-1);
  padding: 2px 0; cursor: default; min-width: 0;
}
.tc-head.expandable { cursor: pointer; }
.tc-head.expandable:hover .tc-name { color: var(--accent); }
.tc-dot { color: var(--s-done); font-size: 9px; flex: none; }
.tc-name { font-weight: 600; color: var(--fg-0); flex: none; }
.tc-arg { color: var(--fg-2); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; min-width: 0; }
.tc-running { color: var(--s-working); font-style: italic; flex: none; }
.tc-caret { color: var(--fg-4); margin-left: auto; font-size: 9px; flex: none; padding-left: 6px; }

/* Expanded tool detail: full command/content block, then output. */
.tc-detail { margin: 3px 0 9px 16px; }
.tc-cmd {
  margin: 0; padding: 8px 11px;
  background: var(--bg-term); border: 1px solid var(--line-soft); border-radius: var(--r-sm);
  color: var(--fg-1); white-space: pre-wrap; word-break: break-word; overflow-x: auto;
  max-height: 300px; font-size: 11.5px; line-height: 1.55;
}
.tc-out {
  margin: 5px 0 0; padding: 8px 11px;
  background: var(--bg-1); border: 1px solid var(--line-soft); border-radius: var(--r-sm);
  color: var(--fg-2); white-space: pre-wrap; word-break: break-word; overflow-x: auto;
  max-height: 360px; font-size: 11.5px; line-height: 1.5;
}
.tc-detail .tc-out:first-child { margin-top: 0; }   /* output-only (no command block) */

.tc-diff {
  margin: 0; border-radius: var(--r-sm); overflow: hidden;
  font-size: 11.5px; line-height: 1.5; border: 1px solid var(--line-soft);
}
.tc-diff-del { background: color-mix(in oklch, var(--s-danger) 15%, transparent); color: var(--fg-1); padding: 0 9px; white-space: pre-wrap; }
.tc-diff-del::before { content: "- "; color: var(--s-danger); }
.tc-diff-add { background: color-mix(in oklch, var(--s-success) 15%, transparent); color: var(--fg-1); padding: 0 9px; white-space: pre-wrap; }
.tc-diff-add::before { content: "+ "; color: var(--s-success); }

/* ── markdown ── */
.turn-prose .md-p { margin: 0 0 9px; }
.turn-prose .md-p:last-child { margin-bottom: 0; }
.turn-prose .md-h { font-family: var(--sans); color: var(--fg-0); line-height: 1.3; margin: 13px 0 6px; font-weight: 650; }
.turn-prose .md-h:first-child { margin-top: 0; }
.turn-prose h3.md-h { font-size: 15px; }

