pane_dir = os.path.expanduser("~/.config/periscope/pane_sessions")
pane_map = {}
for f in glob.glob(pane_dir+"/*"):
    try: pane_map[open(f).read().strip()] = os.path.basename(f)
    except: pass
def alive(pid):
    try: os.kill(int(pid),0); return True
    except: return False
rows=[]
for f in glob.glob(os.path.expanduser("~/.claude/sessions/*.json")):
    try: d=json.load(open(f))
    except: continue
    sid=d.get("sessionId","")
    rows.append((d.get("status"), f"{(time.time()-d.get('updatedAt',0)/1000):.0f}s", alive(d.get("pid")), sid[:8], pane_map.get(sid,"-"), os.path.basename(d.get('cwd',''))))
rows.sort(key=lambda r: r[1])
print(f"{'status':9} {'age':>6} {'alive':5} {'sid':8} {'pane':6} cwd")
for r in rows: print(f"{r[0]:9} {r[1]:>6} {str(r[2]):5} {r[3]:8} {r[4]:6} {r[5]}")
