1	// Right-pane of the split view (#detail). Four states, ported from detail.js:
2	//
3	//   - pane          — <Terminal> + side metadata (pending input / recap / last line)
4	//   - review-live   — idempotent LGTM iframe
5	//   - review-empty  — "Start review →" CTA
6	//   - empty         — nothing selected
7	//
8	// The selection is driven by the `railSelection` signal (string highlight-key:
9	// "pane:<pid>" | "review:<worktree>" | null) — the same value <Rail> writes and
10	// compares rows against. The live window data comes from the `windows` signal,
11	// so the header + side panel refresh on every poll without remounting the
12	// terminal (single-xterm reuse: <Terminal> is keyed on pid, so re-selecting the
13	// same pane preserves the instance — reconnect, not remount; coupling #5 /
14	// detail.js sameMount). `activeTarget` is set BEFORE any short-circuit so the
15	// shared paste handler always targets the current selection.
16	//
17	// CSS contract preserved verbatim: detail-pane/-header/-body, detail-xterm,
18	// detail-side, detail-review/-header/-iframe, detail-empty, review-start-card,
19	// hsep, header-pr/-linear/-ci/-git/-api-error, side-section/-label/-pending/
20	// -prompt/-mono. No class renamed.
21	import { useRef, useEffect, useState } from "preact/hooks";
22	import { windows, activeTarget, railSelection, transcriptMode, transcriptSeen } from "../store.js";
23	import { apiCall, rewriteLgtmHost, prUrl, targetQuery } from "../util.js";
24	import { Terminal } from "../terminal/Terminal.jsx";
25	import { writeTerminalLine, scrollTerminalToBottom, isTerminalAtBottom } from "../terminal/terminalCore.js";
26	import { Sidebar } from "../sidebar/Sidebar.jsx";
27	import { TranscriptView } from "./Transcript.jsx";
28	
29	// Match the modal's /api/pane cadence so the two views feel identical.
30	const DETAIL_POLL_MS = 1500;
31	
32	function lookupWindow(pid) {
33	  return (windows.value || []).find((w) => w.pid === pid) || null;
34	}
35	
36	function computeMode(w) {
37	  if (!w || !w.is_claude) return "terminal";
38	  const explicit = transcriptMode.value[w.pid];
39	  if (explicit) return explicit;
40	  return transcriptSeen.value[w.pid] ? "transcript" : "terminal";
41	}
42	
43	function setTranscriptMode(pid, mode) {
44	  transcriptMode.value = { ...transcriptMode.value, [pid]: mode };
45	}
46	
47	function lgtmSessionForWorktree(worktreeKey) {
48	  const w = (windows.value || []).find((x) => x.session === worktreeKey);
49	  return w?.lgtm?.slug ? w.lgtm : null;
50	}
51	
52	// Shared image-paste handler (capture-phase via Terminal's onPaste). Mirrors
53	// the modal's onPaste exactly: write the pasted image to a temp path on the
54	// pane via /api/paste-image, keyed by the shared activeTarget signal.
55	async function handleDetailPaste(e) {
56	  if (!activeTarget.value) return;
57	  const items = e.clipboardData?.items || [];
58	  for (const item of items) {
59	    if (item.kind !== "file" || !item.type.startsWith("image/")) continue;
60	    const blob = item.getAsFile();
61	    if (!blob) continue;
62	    e.preventDefault();
63	    e.stopPropagation();
64	    try {
65	      const res = await fetch(`/api/paste-image?${targetQuery(activeTarget.value)}`, {
66	        method: "POST",
67	        headers: { "Content-Type": blob.type || "image/png" },
68	        body: blob,
69	      });
70	      const d = await res.json();
71	      if (!d.ok) writeTerminalLine(`\r\n\x1b[31m[periscope: image paste failed: ${d.error}]\x1b[0m`);
72	    } catch (err) {
73	      writeTerminalLine(`\r\n\x1b[31m[periscope: image paste error: ${err.message}]\x1b[0m`);
74	    }
75	    return;
76	  }
77	}
78	
79	// Header for the pane detail — branch · PR · CI · Linear · git · model · ctx% ·
80	// API error · ✨ auto-rename. PR/Linear anchors are real links; they sit
81	// inside a non-clickable header so no stopPropagation is needed here (unlike
82	// the rail rows).
83	function PaneHeader({ w, mode, onMode }) {
84	  const [renaming, setRenaming] = useState(false);
85	
86	  async function autoRename() {
87	    if (renaming) return;
88	    setRenaming(true);
89	    try {
90	      // The endpoint mutates the tmux window's title via Claude; the next
91	      // /api/state poll surfaces the new name in the rail row. No need to
92	      // touch local state — refresh is implicit via the poll loop.
93	      await apiCall("auto-rename window", `/api/auto-rename-window?${targetQuery(w.target)}`, {
94	        method: "POST",
95	      });
96	    } finally {
97	      setRenaming(false);
98	    }
99	  }
100	
101	  const parts = [
102	    <button
103	      type="button"
104	      class={`header-rename${renaming ? " busy" : ""}`}
105	      title="ask Claude to rename this window"
106	      disabled={renaming}
107	      onClick={autoRename}
108	    >
109	      ✨
110	    </button>,
111	    <span><b>{w.session || ""}</b></span>,
112	  ];
113	  if (w.branch) {
114	    parts.push(<><span class="hsep">·</span><span>{w.branch}</span></>);
115	  }
116	  if (w.pr) {
117	    const href = prUrl(w.repo_slug, w.pr);
118	    const ciCls = w.ci === "✓" ? "ci-ok" : w.ci === "✗" ? "ci-bad" : w.ci === "⟳" ? "ci-running" : "";
119	    const ciSpan = w.ci ? <> <span class={`header-ci ${ciCls}`}>{w.ci}</span></> : null;
120	    const inner = <>#{String(w.pr)}{ciSpan}</>;
121	    const prLink = href
122	      ? <a class="header-pr" href={href} target="_blank" rel="noopener">{inner}</a>
123	      : <span class="header-pr">{inner}</span>;
124	    parts.push(<><span class="hsep">·</span>{prLink}</>);
125	  }
126	  if (w.linked_linear) {
127	    const lid = w.linked_linear;
128	    const ltitle = w.linked_linear_title ? `: ${w.linked_linear_title}` : "";
129	    const lstatus = w.linked_linear_status ? ` [${w.linked_linear_status}]` : "";
130	    parts.push(
131	      <>
132	        <span class="hsep">·</span>
133	        <a class="header-linear" href={`https://linear.app/issue/${lid}`} target="_blank" rel="noopener" title={`Linear ${lid}${ltitle}${lstatus}`}>{lid}</a>
134	      </>
135	    );
136	  }
137	  if (w.git && w.git !== "clean") {
138	    parts.push(<><span class="hsep">·</span><span class="header-git">{w.git}</span></>);
139	  }
140	  if (w.is_claude && w.model) {
141	    parts.push(<><span class="hsep">·</span><span>{w.model.replace(/\s*\(.*\)/, "")}</span></>);
142	  }
143	  if (w.is_claude && w.context_pct != null) {
144	    parts.push(<><span class="hsep">·</span><span>{w.context_pct}%</span></>);
145	  }
146	  if (w.api_error) {
147	    parts.push(<><span class="hsep">·</span><span class="header-api-error" title="last tool result was an API error">⚠ API error</span></>);
148	  }
149	  if (w.is_claude) {
150	    parts.push(
151	      <span class="detail-mode-toggle">
152	        <button class={mode === "transcript" ? "is-active" : ""}
153	                onClick={() => onMode("transcript")}>Transcript</button>
154	        <button class={mode === "terminal" ? "is-active" : ""}
155	                onClick={() => onMode("terminal")}>Terminal</button>
156	      </span>
157	    );
158	  }
159	  return <header id="detail-pane-header" class="detail-pane-header">{parts.map((p, i) => <>{p}</>)}</header>;
160	}
161	
162	// Rich per-pane sidebar — Linked / Notes / Activity, fed by a 1.5s poll of
163	// /api/pane (the same endpoint the modal sidebar uses). The poll restarts on
164	// `target` change and tears down when the pane is deselected or the user
165	// switches to a review row (Detail unmounts <PaneDetail>, killing this).
166	//
167	// Pitfall: the inner <Sidebar> mounts <NotesEditor> uncontrolled + keyed on
168	// pid, and the activity-stream scrollTop is preserved across renders. Both
169	// behaviors are coupling-#5 lessons from the modal port; the shared module
170	// preserves them so we don't have to re-derive here.
171	function SidePanel({ target }) {
172	  const [paneData, setPaneData] = useState(null);
173	
174	  useEffect(() => {
175	    if (!target) return;
176	    let alive = true;
177	    async function tick() {
178	      try {
179	        const res = await fetch(`/api/pane?${targetQuery(target)}&lines=80`);
180	        if (!res.ok) return;
181	        const d = await res.json();
182	        if (alive) setPaneData(d);
183	      } catch (_) {}
184	    }
185	    tick();
186	    const h = setInterval(tick, DETAIL_POLL_MS);
187	    return () => { alive = false; clearInterval(h); };
188	  }, [target]);
189	
190	  // While the first /api/pane response is in flight, render the bare aside so
191	  // the grid track keeps its 240px column (no width-jump when data lands).
192	  if (!paneData) return <aside id="detail-side" class="detail-side" />;
193	
194	  return (
195	    <Sidebar
196	      data={paneData}
197	      onRefresh={() => {}}
198	      containerId="detail-side"
199	      containerClass="detail-side"
200	      idPrefix="detail"
201	    />
202	  );
203	}
204	
205	// Pane state. The <Terminal> is keyed on pid: re-selecting the same pid keeps
206	// the instance (reconnect-not-remount), a different pid unmounts+remounts.
207	// activeTarget is set on every render so the shared paste handler tracks the
208	// live target even when the same pane stays selected.
209	function PaneDetail({ w }) {
210	  const mode = computeMode(w);
211	  // Set the shared paste/active-target before anything else (coupling #5).
212	  useEffect(() => {
213	    activeTarget.value = w.target;
214	  }, [w.target]);
215	
216	  // Publish the pane header's height as --detail-header-h so the (absolutely
217	  // positioned, kept-mounted) transcript host can sit exactly below it. The
218	  // header flex-wraps (PR/branch/model chips), so its height is dynamic — a
219	  // ResizeObserver keeps the offset correct instead of a magic constant.
220	  useEffect(() => {
221	    const el = document.getElementById("detail-pane-header");
222	    const detail = document.getElementById("detail");
223	    if (!el || !detail) return;
224	    const apply = () => detail.style.setProperty("--detail-header-h", el.offsetHeight + "px");
225	    apply();
226	    const ro = new ResizeObserver(apply);
227	    ro.observe(el);
228	    return () => ro.disconnect();
229	  }, [w.target]);
230	
231	  // Switching to terminal mode un-hides the xterm; pin it to the live bottom
232	  // (it otherwise shows wherever it was last scrolled — often the top).
233	  useEffect(() => {
234	    if (mode !== "terminal") return;
235	    const r = requestAnimationFrame(() => requestAnimationFrame(scrollTerminalToBottom));
236	    return () => cancelAnimationFrame(r);
237	  }, [mode]);
238	
239	  // Show the scroll-to-bottom button only when scrolled up. Poll the terminal's
240	  // position while it's the visible mode (cheap buffer read; ~instant feel).
241	  const [atBottom, setAtBottom] = useState(true);
242	  useEffect(() => {
243	    if (mode !== "terminal") return;
244	    const tick = () => setAtBottom(isTerminalAtBottom());
245	    tick();
246	    const h = setInterval(tick, 250);
247	    return () => clearInterval(h);
248	  }, [mode, w.pid]);
249	
250	  return (
251	    <div id="detail-pane" class="detail-pane">
252	      <PaneHeader w={w} mode={mode} onMode={(next) => setTranscriptMode(w.pid, next)} />
253	      <div class="detail-pane-body">
254	        <div class="detail-term-host" style={mode === "terminal" ? "display:contents" : "display:none"}>
255	          <Terminal
256	            key={w.pid}
257	            id="detail-xterm"
258	            class="detail-xterm"
259	            target={w.target}
260	            onPaste={handleDetailPaste}
261	          />
262	        </div>
263	        {/* Keyed on target so switching panes wipes paneData rather than
264	            showing the previous pane's PR/notes for ~1.5s until the new tick
265	            lands. SidePanel takes `target`, NOT `w`. */}
266	        <SidePanel key={w.target} target={w.target} />
267	      </div>
268	      {mode === "terminal" && !atBottom && (
269	        <button
270	          class="term-scroll-bottom"
271	          title="Scroll to latest"
272	          onClick={scrollTerminalToBottom}
273	        >
274	          ⤓
275	        </button>
276	      )}
277	    </div>
278	  );
279	}
