281	// Review state — live LGTM iframe. Idempotent: the iframe element persists and
282	// its src is reassigned ONLY when the (worktree → url) key changes; never per
283	// poll (that kills the SSE). Keyed on worktreeKey at the call site so switching
284	// worktrees tears down + remounts. activeTarget is cleared (review owns the
285	// iframe, no pane target).
286	function ReviewDetail({ worktreeKey }) {
287	  // The LGTM iframe is created imperatively ONCE and parked inside a host div
288	  // Preact owns; Preact never reconciles the iframe node, so the 1.5s/3s poll
289	  // re-render can't move/recreate it (which reloads an iframe in a browser and
290	  // drops the user's in-iframe file selection). Mirrors vanilla's static
291	  // iframe. `display:contents` keeps it laid out as a flex child of #detail-review.
292	  const hostRef = useRef(null);
293	  const iframeRef = useRef(null);
294	  const mountedSrc = useRef(null);
295	  const everHadSession = useRef(false);
296	  const session = lgtmSessionForWorktree(worktreeKey);
297	  const hasSession = !!(session && session.url);
298	  if (hasSession) everHadSession.current = true;
299	  // Use LGTM's EMBEDDING contract (?embedded=1&host=periscope), same as the
300	  // modal review — NOT the bare standalone URL. The bare URL boots LGTM's full
301	  // standalone app whose /events SSE fails when iframed, making LGTM reload
302	  // itself in a loop. Embedded mode is the iframe-designed path and is stable
303	  // (the modal review proves it).
304	  const url = hasSession
305	    ? `${rewriteLgtmHost(session.url)}?embedded=1&host=periscope`
306	    : null;
307	
308	  useEffect(() => {
309	    activeTarget.value = null;
310	  }, [worktreeKey]);
311	
312	  useEffect(() => {
313	    if (!hostRef.current || iframeRef.current) return;
314	    const f = document.createElement("iframe");
315	    f.id = "detail-review-iframe";
316	    f.className = "detail-review-iframe";
317	    hostRef.current.appendChild(f);
318	    iframeRef.current = f;
319	  });
320	
321	  useEffect(() => {
322	    if (url && iframeRef.current && mountedSrc.current !== url) {
323	      iframeRef.current.src = url;
324	      mountedSrc.current = url;
325	    }
326	  }, [url]);
327	
328	  // No session yet for this worktree → Start-review CTA. (Once a session has
329	  // existed, everHadSession keeps us on the iframe even across a transient gap.)
330	  if (!everHadSession.current) {
331	    return <ReviewStart worktreeKey={worktreeKey} />;
332	  }
333	
334	  return (
335	    <div id="detail-review" class="detail-review">
336	      <header id="detail-review-header" class="detail-review-header">
337	        <span><b>review</b></span>
338	        <span class="hsep">·</span>
339	        <span>{worktreeKey}</span>
340	      </header>
341	      <div ref={hostRef} class="detail-review-iframe-host" style="display:contents" />
342	    </div>
343	  );
344	}
345	
346	// Review-empty CTA. "Start review →" POSTs /api/lgtm/start with the worktree
347	// cwd; after start, the next /api/state poll surfaces lgtm.slug and this row
348	// transitions to ReviewDetail (the iframe mounts on the CTA→live transition).
349	function ReviewStart({ worktreeKey }) {
350	  async function start() {
351	    const w = (windows.value || []).find((x) => x.session === worktreeKey);
352	    if (!w) return;
353	    await apiCall("start review", "/api/lgtm/start", {
354	      method: "POST",
355	      headers: { "Content-Type": "application/json" },
356	      body: JSON.stringify({ cwd: w.cwd }),
357	    });
358	    // No explicit selectReview re-call: the next poll flips lgtm.slug on, and
359	    // the signal-driven render swaps in <ReviewDetail> automatically.
360	  }
361	
362	  return (
363	    <div id="detail-review-start" class="detail-review-start">
364	      <div class="review-start-card">
365	        <div class="review-start-title">No LGTM session for this worktree</div>
366	        <button class="review-start-btn" onClick={start}>Start review →</button>
367	      </div>
368	    </div>
369	  );
370	}
371	
372	function EmptyDetail() {
373	  // Markup matches vanilla detail.js:showEmpty verbatim, incl. the
374	  // #detail-empty-add button. It opens the + open picker via the same window
375	  // bridge the rail's "+ open" uses (registered by OpenPickerModal when the
376	  // overlays surface is mounted; a no-op if it isn't).
377	  return (
378	    <div id="detail-empty" class="detail-empty">
379	      <div class="detail-empty-card">
380	        <p>
381	          Select a tab on the left, or{" "}
382	          <button id="detail-empty-add" onClick={() => window.__periscopeOpenPicker?.()}>
383	            + open
384	          </button>{" "}
385	          to add one.
386	        </p>
387	      </div>
388	    </div>
389	  );
390	}
391	
392	export function Detail() {
393	  const sel = railSelection.value;       // string highlight-key, or null
394	  const ws = windows.value || [];        // read so Detail re-renders each poll
395	
396	  const isReview = !!sel && sel.startsWith("review:");
397	  const isPane = !!sel && sel.startsWith("pane:");
398	  const activeReviewWt = isReview ? sel.slice("review:".length) : null;
399	
400	  // Keep EVERY opened review's iframe mounted (CSS-hidden when not active), so
401	  // switching among reviews/panes never reloads a review — each loads exactly
402	  // once. Display toggling never reloads an iframe (it stays in the DOM).
403	  // Mirrors how the modal keeps its review iframe alive across tab switches.
404	  // The opened set is pruned to worktrees still live in /api/state, so a
405	  // closed worktree's iframe is torn down rather than leaking.
406	  const opened = useRef(new Set());
407	  if (activeReviewWt) opened.current.add(activeReviewWt);
408	  const liveSessions = new Set(ws.map((w) => w.session));
409	  for (const wt of [...opened.current]) {
410	    if (wt !== activeReviewWt && !liveSessions.has(wt)) opened.current.delete(wt);
411	  }
412	  const reviewWts = [...opened.current];
413	
414	  const paneW = isPane ? lookupWindow(sel.slice("pane:".length)) : null;
415	
416	  // Keep every opened Claude transcript mounted (CSS-hidden when not active) so
417	  // scroll position + expanded segments survive pane switches — same discipline
418	  // as the review iframes. Pruned to pids still live in /api/state.
419	  const openedTr = useRef(new Set());
420	  if (isPane && paneW?.is_claude) openedTr.current.add(paneW.pid);
421	  const livePids = new Set(ws.map((x) => x.pid));
422	  const selMode = computeMode(paneW);
423	  for (const pid of [...openedTr.current]) {
424	    const isSelected = isPane && paneW?.pid === pid;
425	    if (!isSelected && !livePids.has(pid)) openedTr.current.delete(pid);
426	  }
427	  const trPids = [...openedTr.current];
428	
429	  return (
430	    <section id="detail">
431	      {!sel && <EmptyDetail />}
