1	// One pane card. Ported from grid.js:renderCard / renderCardMeta /
2	// renderCardActivity / renderCardFooter. JSX auto-escapes, so escapeHtml
3	// drops; the inline `onclick="event.stopPropagation()"` on PR/Linear anchors
4	// becomes a real onClick calling e.stopPropagation() (convention #4 —
5	// without it, clicking a PR link opens the modal).
6	//
7	// CSS contract preserved verbatim: state-${w.state} card class, card-channel-
8	// ${kind} tint, card-needs-attention pulse, card-pr-fail bundle, dot classes,
9	// and every card-* / channel-dot / session-* class name. No renames.
10	//
11	// Must-not-drop:
12	//  - status-label priority: needs-input beats spinner verb beats raw state
13	//    (convention #6).
14	//  - unread-alert override + card-channel-${kind} tint.
15	//  - needs-attention pulse only for need_human.
16	//  - promote gating: project_pinned_dir === "__main__" AND aff.kind && != no-repo.
17	//  - CI ✗ bundled into card-pr-fail.
18	//  - footer model parenthetical strip + relTime(focused_at).
19	import { useRef, useEffect } from "preact/hooks";
20	import { signal } from "@preact/signals";
21	import { relTime, prUrl, targetQuery, apiCall } from "../util.js";
22	import * as prefs from "../prefs.js";
23	import { editingTarget } from "../store.js";
24	import { poll, openModal } from "./poll.js";
25	import { confirmDialog } from "../overlays/Dialog.jsx";
26	import { CARD_MIME } from "./dnd.js";
27	
28	function CiSpan({ ci }) {
29	  if (!ci) return null;
30	  const cls = ci === "✓" ? "card-ci-ok" : ci === "✗" ? "card-ci-bad" : "card-ci-pending";
31	  return <span class={cls}>{ci}</span>;
32	}
33	
34	// `git` from server is "clean" or "+N -M [*]". Split for separate styling.
35	function GitMeta({ git }) {
36	  if (!git) return null;
37	  if (git === "clean") return <span class="card-clean">clean</span>;
38	  return <span class="card-dirty">{git}</span>;
39	}
40	
41	// Meta row: branch · clean/dirty · #PR ci · linear · worktree-chip · lgtm.
42	// Parts are interleaved with the `·` card-dot separator — once between
43	// adjacent parts only, no leading/trailing (joinWithDots semantics).
44	function CardMeta({ w, aff, onLgtm }) {
45	  const parts = [];
46	
47	  if (w.branch) parts.push(<span class="card-branch">{w.branch}</span>);
48	  if (w.git) parts.push(<GitMeta git={w.git} />);
49	
50	  if (w.pr) {
51	    const linkedTitle = w.pr_linked ? " (linked by claude)" : "";
52	    const linkedClass = w.pr_linked ? " card-pr-linked" : "";
53	    const prHref = prUrl(w.repo_slug, w.pr);
54	    const prLink = prHref ? (
55	      <a
56	        class={`card-pr${linkedClass}`}
57	        href={prHref}
58	        target="_blank"
59	        rel="noopener"
60	        onClick={(e) => e.stopPropagation()}
61	        title={`PR #${w.pr}${linkedTitle}`}
62	      >
63	        #{w.pr}
64	      </a>
65	    ) : (
66	      <span class={`card-pr${linkedClass}`} title={`PR #${w.pr}${linkedTitle}`}>
67	        #{w.pr}
68	      </span>
69	    );
70	    if (w.ci === "✗") {
71	      // Bundle #PR + ✗ into a single red badge so the failure mode is
72	      // immediately legible without claiming the card's state accent.
73	      parts.push(
74	        <span class="card-pr-fail">
75	          {prLink}
76	          <span class="card-ci-bad">✗</span>
77	        </span>
78	      );
79	    } else {
80	      parts.push(
81	        <>
82	          {prLink}
83	          {w.ci ? <> <CiSpan ci={w.ci} /></> : null}
84	        </>
85	      );
86	    }
87	  }
88	
89	  if (w.linked_linear) {
90	    const lid = w.linked_linear;
91	    const ltitle = w.linked_linear_title ? `: ${w.linked_linear_title}` : "";
92	    const lstatus = w.linked_linear_status ? ` [${w.linked_linear_status}]` : "";
93	    parts.push(
94	      <a
95	        class="card-linear"
96	        href={`https://linear.app/issue/${lid}`}
97	        target="_blank"
98	        rel="noopener"
99	        onClick={(e) => e.stopPropagation()}
100	        title={`Linear ${lid}${ltitle}${lstatus} (linked by claude)`}
101	      >
102	        {lid}
103	      </a>
104	    );
105	  }
106	
107	  if (aff.kind === "sibling") {
108	    parts.push(
109	      <span
110	        class="card-worktree-chip card-worktree-chip-sibling"
111	        title="this tab is in a sibling worktree of the project's repo"
112	      >
113	        ↪ {aff.label || ""}
114	      </span>
115	    );
116	  } else if (aff.kind === "off-repo") {
117	    parts.push(
118	      <span
119	        class="card-worktree-chip card-worktree-chip-off-repo"
120	        title="this tab's cwd is outside the project's repo"
121	      >
122	        ⚠ {aff.label || ""}
123	      </span>
124	    );
125	  }
126	
127	  if (w.lgtm) {
128	    const total = (w.lgtm.claude_comments || 0) + (w.lgtm.user_comments || 0);
129	    const tip = total > 0
130	      ? `LGTM review · ${total} comment${total === 1 ? "" : "s"}`
131	      : "LGTM review (no comments)";
132	    parts.push(
133	      <button
134	        type="button"
135	        class="card-lgtm"
136	        data-lgtm-badge
137	        data-target={w.target}
138	        title={tip}
139	        onClick={(e) => {
140	          e.stopPropagation();
141	          onLgtm();
142	        }}
143	      >
144	        👁 review{total > 0 ? <> <span class="card-lgtm-n">{total}</span></> : null}
145	      </button>
146	    );
147	  }
148	
149	  if (!parts.length) return null;
150	  return (
151	    <div class="card-meta">
152	      {parts.map((p, i) => (
153	        <>
154	          {i > 0 ? <> <span class="card-dot">·</span> </> : null}
155	          {p}
156	        </>
157	      ))}
158	    </div>
159	  );
160	}
161	
162	// Activity row. Priority: unread Claude alert > pending_input > recap >
163	// last_line. is-shell when it's a bare shell pane with nothing claude-shaped.
164	function CardActivity({ w, unreadAlert, channelKind }) {
165	  if (unreadAlert) {
166	    return (
167	      <div class={`card-activity is-channel is-channel-${channelKind}`}>
