473	function statusDotClass(s) {
474	  if (s === "needs-input") return "dot dot-alert dot-pulse";
475	  if (s === "working") return "dot dot-green";
476	  if (s === "done") return "dot dot-blue";
477	  if (s === "idle") return "dot dot-grey";
478	  return "dot dot-none";
479	}
480	
481	function ciClass(ci) {
482	  if (ci === "✓") return "ok";
483	  if (ci === "✗") return "bad";
484	  if (ci === "⟳") return "running";
485	  return "neutral";
486	}
