488	// Inline-rename label. `kind` is "pane" or "worktree" (only those rename).
489	// `onCommit(next)` does the network write; `label` is the bold/plain display
490	// node. Non-renameable rows just render the label.
491	function RailLabel({ label, kind, renameable, onCommit }) {
492	  const [editing, setEditing] = useState(false);
493	  const inputRef = useRef(null);
494	  const settled = useRef(false);
495	
496	  useEffect(() => {
497	    if (editing && inputRef.current) {
498	      inputRef.current.focus();
499	      inputRef.current.select();
500	    }
501	  }, [editing]);
502	
503	  function begin(e) {
504	    if (!renameable) return;
505	    e.preventDefault();
506	    e.stopPropagation();
507	    settled.current = false;
508	    setEditing(true);
509	  }
510	
511	  function commit(value) {
512	    if (settled.current) return;
513	    settled.current = true;
514	    setEditing(false);
515	    const next = (value || "").trim();
516	    if (next && next !== label) onCommit(next);
517	  }
518	  function cancel() {
519	    if (settled.current) return;
520	    settled.current = true;
521	    setEditing(false);
522	  }
523	
524	  if (editing) {
525	    return (
526	      <span class="rail-label">
527	        <input
528	          ref={inputRef}
529	          type="text"
530	          class="rail-rename-input"
531	          value={label}
532	          spellcheck={false}
533	          onClick={(e) => e.stopPropagation()}
534	          onKeyDown={(e) => {
535	            e.stopPropagation();
536	            if (e.key === "Enter") { e.preventDefault(); commit(e.currentTarget.value); }
