542	    );
543	  }
544	  // worktree/repo labels render bold; pane labels plain.
545	  return (
546	    <span class="rail-label" onDblClick={renameable ? begin : undefined}>
547	      {kind === "pane" ? label : <b>{label}</b>}
548	    </span>
549	  );
