711	// rail.js:mergeLiveAndPrefs (+ its severity rollup + repo-label helper) — no
712	// behavior change. Kept pure (no signals, no DOM) because it's consumed TWICE:
713	// once to render <Rail>, and once as `currentMergedOrder()`'s seed for the
714	// drag-reorder splices (so a drag operates on the order the user actually
715	// sees, not raw prefs which may be missing auto-populated entries).
716	//
717	// OTHER_REPO_KEY is pinned to the bottom at every one of the four points the
718	// rail enforces it: merge (here), isValidDropTarget, reorderRepos, and the
719	// repoRow drag-attr gate (in Rail.jsx).
720	
721	// Synthetic repo key for non-worktree-backed sessions (bare shells, non-git
722	// cwds). Renders as a top-level "Other" group at the bottom with sessions as
723	// direct children (no review row, no branch).
724	export const OTHER_REPO_KEY = "__other__";
725	
726	// Severity ranking for status rollup: higher index = higher priority.
727	const SEVERITY = ["shell", "idle", "done", "working", "needs-input"];
728	
729	export function maxSeverity(states) {
730	  let best = -1;
731	  for (const s of states) {
732	    const i = SEVERITY.indexOf(s);
733	    if (i > best) best = i;
734	  }
735	  return best >= 0 ? SEVERITY[best] : "shell";
736	}
737	
738	// Merge live /api/state windows with persisted ordering prefs to produce the
739	// actual rail tree. Live windows ARE the membership; prefs are ordering hints —
740	// entries in pref order come first (in their pref position), then new live
741	// entries append. Pref entries for repos/worktrees/panes that are no longer
742	// live are silently dropped from the rendered output.
743	export function mergeLiveAndPrefs(windows, prefRepoOrder, prefWtByRepo, prefPanesByWt) {
744	  const liveByRepo = {};       // repo_key → ordered list of session names (first-seen wins)
745	  const livePanesByWt = {};    // session name → ordered list of pane pids (first-seen)
746	  for (const w of (windows || [])) {
747	    const r = w.repo_key || OTHER_REPO_KEY;
748	    const s = w.session;
749	    if (!liveByRepo[r]) liveByRepo[r] = [];
750	    if (!liveByRepo[r].includes(s)) liveByRepo[r].push(s);
751	    if (!livePanesByWt[s]) livePanesByWt[s] = [];
752	    if (!livePanesByWt[s].includes(w.pid)) livePanesByWt[s].push(w.pid);
753	  }
754	
755	  // Repo order: prefs first (filtered to live), then live-new appended.
756	  // "Other" always lands at the bottom regardless of pref order — it's a
757	  // catch-all bucket, not a peer to real repos.
758	  const liveRepoSet = new Set(Object.keys(liveByRepo));
759	  const realRepos = [...prefRepoOrder.filter(r => liveRepoSet.has(r) && r !== OTHER_REPO_KEY),
760	                     ...Object.keys(liveByRepo).filter(r => !prefRepoOrder.includes(r) && r !== OTHER_REPO_KEY)];
761	  const repoOrder = liveRepoSet.has(OTHER_REPO_KEY)
762	    ? [...realRepos, OTHER_REPO_KEY]
763	    : realRepos;
764	
765	  // Worktree order per repo: same logic.
766	  const worktreesByRepo = {};
767	  for (const r of repoOrder) {
768	    const live = liveByRepo[r] || [];
769	    const liveSet = new Set(live);
770	    const pref = (prefWtByRepo[r] || []).filter(w => liveSet.has(w));
771	    const prefSet = new Set(pref);
772	    worktreesByRepo[r] = [...pref, ...live.filter(w => !prefSet.has(w))];
773	  }
774	
775	  // Pane-children order per worktree: prefs first (filtered), then new live
776	  // pids. The "review" sentinel is auto-added for git-backed worktrees only —
777	  // non-worktree sessions under "Other" have no review row.
778	  const panesByWorktree = {};
779	  for (const r of repoOrder) {
780	    const isOther = r === OTHER_REPO_KEY;
781	    for (const w of worktreesByRepo[r]) {
782	      const live = livePanesByWt[w] || [];
783	      const liveSet = new Set(live);
784	      const pref = prefPanesByWt[w] || [];
785	      const prefKept = pref.filter(c => (c === "review" && !isOther) || liveSet.has(c));
786	      const prefSet = new Set(prefKept);
787	      const merged = [...prefKept, ...live.filter(p => !prefSet.has(p))];
788	      if (!isOther && !merged.includes("review")) merged.push("review");
789	      panesByWorktree[w] = merged;
790	    }
791	  }
792	
793	  return { repoOrder, worktreesByRepo, panesByWorktree };
794	}
795	
796	// Build a quick { worktreeKey: [windowObj, ...] } map from /api/state windows.
797	export function indexWindowsByWorktree(windows) {
798	  const out = {};
799	  for (const w of (windows || [])) {
800	    const key = w.session;  // worktree_key = session name
801	    (out[key] = out[key] || []).push(w);
802	  }
803	  return out;
804	}
805	
806	// Look up the human-readable repo label for a repo_key. Pulled off any window
807	// whose `repo_key` matches; falls back to basename of the repo_key path. The
808	// synthetic OTHER_REPO_KEY renders as "Other".
809	export function repoLabelFor(repoKey, windows) {
810	  if (repoKey === OTHER_REPO_KEY) return "Other";
811	  for (const w of (windows || [])) {
812	    if (w.repo_key === repoKey && w.repo_label) return w.repo_label;
813	  }
814	  const parts = String(repoKey || "").split("/").filter(Boolean);
815	  return parts[parts.length - 1] || repoKey;
816	}
