import subprocess
# build ppid->children map
out=subprocess.run(["ps","-axo","pid=,ppid=,comm="],capture_output=True,text=True).stdout
kids={}
comm={}
for line in out.splitlines():
    parts=line.split(None,2)
    if len(parts)<3: continue
    pid,ppid,c=int(parts[0]),int(parts[1]),parts[2]
    kids.setdefault(ppid,[]).append(pid); comm[pid]=c
def walk(pid,d=0):
    print("   "*d + f"{pid} {comm.get(pid,'?').rsplit('/',1)[-1]}")
    for k in kids.get(pid,[])[:12]: walk(k,d+1)
for root in (16241,99431):
    print(f"--- tree for {root} ---")
    walk(root)
